<?php
namespace App\Http\Controllers;
use App\Models\Book; use App\Models\Category; use Illuminate\Http\Request;
class BookController extends Controller {public function index(Request $r){$q=$r->input('q');$category=$r->input('category');$books=Book::with('category')->when($q,fn($x)=>$x->where(fn($w)=>$w->where('title','like',"%$q%")->orWhere('author','like',"%$q%")))->when($category,fn($x)=>$x->where('category_id',$category))->latest()->get();return view('books.index',compact('books','q','category')+['categories'=>Category::orderBy('name')->get()]);} public function create(){return view('books.create',['categories'=>Category::orderBy('name')->get()]);} public function store(Request $r){$data=$r->validate(['title'=>'required','author'=>'required','publisher'=>'required','year'=>'required|integer','stock'=>'required|integer|min:0','category_id'=>'required|exists:categories,id']);Book::create($data);return redirect()->route('books.index')->with('success','Buku berhasil ditambahkan.');} public function show(Book $book){$book->load('category');return view('books.show',compact('book'));} public function edit(Book $book){return view('books.edit',['book'=>$book,'categories'=>Category::orderBy('name')->get()]);} public function update(Request $r,Book $book){$data=$r->validate(['title'=>'required','author'=>'required','publisher'=>'required','year'=>'required|integer','stock'=>'required|integer|min:0','category_id'=>'required|exists:categories,id']);$book->update($data);return redirect()->route('books.index')->with('success','Buku berhasil diperbarui.');} public function destroy(Book $book){$book->delete();return redirect()->route('books.index')->with('success','Buku berhasil dihapus.');}}
